.dark{--sx-r-card:3px;--sx-r-md:2px;--sx-r-btn:2px;--sx-card:inset 0 1px 0 rgb(255 255 255 / 0.035), 0 0 0 1px rgb(255 255 255 / 0.045), 0 1px 2px rgb(0 0 0 / 0.35), 0 10px 30px -12px rgb(0 0 0 / 0.55);--sx-pop:inset 0 1px 0 rgb(255 255 255 / 0.06), 0 0 0 1px rgb(255 255 255 / 0.08), 0 4px 12px -4px rgb(0 0 0 / 0.45), 0 18px 48px -12px rgb(0 0 0 / 0.6);--sx-edge:inset 0 1px 0 rgb(255 255 255 / 0.04);--sx-btn:none;--sx-pill:inset 0 1px 0 rgb(255 255 255 / 0.04), 0 0 0 1px rgb(255 255 255 / 0.05), 0 1px 2px rgb(0 0 0 / 0.35);--sx-accent:#ece7e5;--sx-accent-2:#ada4a1;--sx-accent-ink:#ece7e5;--sx-accent-fill:#ece7e5;--sx-accent-fg:#150c0c;--sx-glow:color-mix(in srgb, #ece7e5 calc(50% * var(--sx-glow-k)), transparent);--sx-rim-c:linear-gradient(to bottom right,#bcd1fd,#9edcf3,#a0e1ce);--sx-ambient:6%;--sx-tint:#ece7e526;--sx-ring:#ada4a1;--sx-line:rgb(255 251 251 / 0.149);--sx-line-3:rgb(255 251 251 / 0.239);--sx-fg:#ece7e5;--sx-card-bg:#1f1515;--sx-fg-2:#b1a8a5;--sx-fg-3:#b0a8a5;--sx-fg-4:#766e6b;--sx-sunken:#120909;--sx-raised:#261c1c;--sx-hover:rgb(255 251 251 / 0.043);--sx-seg:inset 0 1px 0 rgb(255 255 255 / 0.06), 0 0 0 1px rgb(255 251 251 / 0.149), 0 1px 3px rgb(0 0 0 / 0.4);--sx-veil:rgb(0 0 0 / 0.36)}
