[data-workspace-area="conversation"]{background-image:var(--sx-actor-2),radial-gradient(120% 55% at 50% -12%,color-mix(in srgb,var(--sx-accent) var(--sx-ambient),transparent),transparent 62%)!important;background-size:420px 230px,100% 100%!important;background-position:right 3% bottom 84px,0 0!important;background-repeat:no-repeat,no-repeat!important}
[data-workspace-area="conversation"]::before{background:var(--sx-pc);-webkit-mask:var(--sx-actor) 0 0/340px 420px,linear-gradient(transparent,#000 45%);-webkit-mask-composite:source-in;mask:var(--sx-actor) 0 0/340px 420px,linear-gradient(transparent,#000 45%);mask-composite:intersect;opacity:.7}
